\title{Spectral Theory of Random Walks on Cayley Graphs of Finite Abelian Groups}
\author{Aristotle}
\date{July 10, 2026}

\begin{document}

\begin{abstract}
We develop, from first principles, the spectral theory underlying classical and
quantum random walks on Cayley graphs of finite abelian groups. The organizing
principle is that the \emph{characters} of a finite abelian group $G$ simultaneously
diagonalize every translation-invariant operator on $\ell^2(G)$ --- in particular
the adjacency (walk) operator of any Cayley graph $\Cay(G,S)$. From this single fact
we obtain: unitarity of the elementary shift operator; exact periodicity of the
single-generator walk, with period equal to the additive order of the generator; a
complete family of eigenvectors (the characters) with explicit eigenvalues
$\lambda_\psi = \sum_{s\in S}\psi(s)$; the Perron--Frobenius bound
$|\lambda_\psi|\le|S|$; self-adjointness of the walk operator for symmetric
generating sets; and, for the cycle $\Cay(\Z/n\Z,\{\pm1\})$, the exact second
eigenvalue $2\cos(2\pi/n)$ together with the strict positivity of the spectral gap.
We explain how the spectral gap controls mixing time, work the cycle and hypercube
as fully explicit examples, and outline the extension to non-abelian groups via
representation theory.
\end{abstract}

\maketitle

\section{Introduction}

Random walks on graphs are a unifying object across mathematics, physics, and
computer science. On a finite, connected, non-bipartite graph, a random walk
converges to a stationary distribution, and the rate of convergence --- the
\emph{mixing time} --- is controlled by the \emph{spectral gap} of the walk
operator. The central analytic task is therefore to compute the eigenvalues of that
operator.

For a generic graph this is hard. But when the graph carries the symmetry of a group
--- when it is a \textbf{Cayley graph} --- much becomes computable. For a finite
\emph{abelian} group the computation is essentially closed-form: the characters of
the group form a simultaneous eigenbasis for every Cayley operator, reducing
spectral analysis to a finite sum of roots of unity. This paper presents that theory
self-containedly and derives the concrete consequences for mixing.

The same framework anchors the study of \emph{quantum} walks. The elementary step of
a Cayley walk --- translation by a group element --- is a unitary operator, and its
iterates are periodic: precisely the length-preserving, reversible dynamics required
of a quantum evolution. The abelian spectral theory developed here is thus the
common base case for both the classical mixing-time program and its quantum analogue.

\section{Setup and notation}

Let $G$ be a finite abelian group, written additively, with identity $0$. We model
the Hilbert space of states as $\ell^2(G) = \{ f : G \to \C \}$, with
\[
\langle f, g\rangle = \sum_{x\in G} \overline{f(x)}\,g(x), \qquad
\|f\|^2 = \sum_{x\in G} |f(x)|^2 .
\]
A \textbf{generating (multi)set} is a finite subset $S \subseteq G$. The
\textbf{Cayley graph} $\Cay(G,S)$ has vertex set $G$ and an edge from $x$ to $x+s$
for each $s\in S$; it is $|S|$-regular and vertex-transitive. We call $S$
\textbf{symmetric} if $S=-S$, which makes $\Cay(G,S)$ undirected.

An \textbf{additive character} of $G$ is a homomorphism $\psi:(G,+)\to\C^\times$.
Since $G$ is finite, $\psi$ takes values in roots of unity: $|\psi(x)|=1$,
$\psi(x+y)=\psi(x)\psi(y)$, and $\psi(0)=1$.

\section{The operators}

\begin{definition}[Shift]
For $s\in G$, the \emph{shift} operator $\shift_s:\ell^2(G)\to\ell^2(G)$ is
$(\shift_s f)(x) = f(x+s)$.
\end{definition}

\begin{definition}[Walk / adjacency operator]
For finite $S\subseteq G$, the \emph{Cayley walk operator} is
$(A_S f)(x) = \sum_{s\in S} f(x+s)$, i.e. $A_S=\sum_{s\in S}\shift_s$. The normalized
\emph{random-walk operator} is $P=|S|^{-1}A_S$.
\end{definition}

\begin{definition}[Character eigenvalue]
For $S$ and a character $\psi$, define $\displaystyle \lambda_\psi(S)=\sum_{s\in S}\psi(s)$.
\end{definition}

\section{Algebra and dynamics of the shift}

\begin{lemma}[Group law and linearity]
$\shift_s\circ\shift_t=\shift_{s+t}$, $\shift_0=\Id$, each $\shift_s$ is
$\C$-linear, and $\shift_{-s}$ inverts $\shift_s$; hence $\shift_s$ is a linear
bijection of $\ell^2(G)$.
\end{lemma}
\begin{proof}
$(\shift_s(\shift_t f))(x)=f(x+s+t)$ by associativity and commutativity; the other
claims are immediate, and $\shift_{-s}(\shift_s f)(x)=f(x)$.
\end{proof}

\begin{theorem}[Unitarity of the shift]
For finite $G$ and $s\in G$, $\|\shift_s f\|^2=\|f\|^2$.
\end{theorem}
\begin{proof}
The map $x\mapsto x+s$ is a bijection of $G$; reindexing,
$\sum_x |f(x+s)|^2=\sum_y|f(y)|^2$.
\end{proof}

\begin{theorem}[Iteration]
For every $k\in\mathbb{N}$, $(\shift_s)^k=\shift_{k\cdot s}$.
\end{theorem}
\begin{proof}
Induction on $k$: base $\shift_0=\Id$; step uses $(k{+}1)\cdot s=k\cdot s+s$.
\end{proof}

\begin{theorem}[Periodicity]
Let $m=\ord(s)$ be the additive order of $s$. Then $(\shift_s)^m=\Id$.
\end{theorem}
\begin{proof}
$(\shift_s)^m=\shift_{m\cdot s}=\shift_0=\Id$.
\end{proof}

In quantum-walk language, the single-generator unitary $U=\shift_s$ satisfies
$U^m=I$: the walk is exactly periodic with period dividing $\ord(s)$.

\begin{theorem}[Translation invariance]
For finite $S$ and $t\in G$, $A_S\circ\shift_t=\shift_t\circ A_S$.
\end{theorem}
\begin{proof}
Both sides send $f$ to $x\mapsto\sum_{s\in S}f(x+t+s)$.
\end{proof}

\section{Spectral diagonalization by characters}

\begin{theorem}[Characters are eigenvectors]
For every finite $S\subseteq G$ and character $\psi$,
\[
A_S\,\psi=\lambda_\psi(S)\,\psi,\qquad \lambda_\psi(S)=\sum_{s\in S}\psi(s).
\]
\end{theorem}
\begin{proof}
For each $x$,
$(A_S\psi)(x)=\sum_{s\in S}\psi(x+s)=\sum_{s\in S}\psi(x)\psi(s)
=\big(\sum_{s\in S}\psi(s)\big)\psi(x)$.
\end{proof}

Since $G$ has exactly $|G|$ characters and these form an orthogonal basis of
$\ell^2(G)$, the theorem gives a complete diagonalization of $A_S$.

\begin{corollary}[Top eigenvalue]
For the trivial character $\psi\equiv1$, $\lambda_\psi(S)=|S|$, with the constant
function as eigenvector.
\end{corollary}

\begin{theorem}[Perron--Frobenius bound]
For every character $\psi$, $|\lambda_\psi(S)|\le|S|$.
\end{theorem}
\begin{proof}
$\big|\sum_{s\in S}\psi(s)\big|\le\sum_{s\in S}|\psi(s)|=|S|$.
\end{proof}

\begin{lemma}[Conjugate of a character]
For a character $\psi$ of a finite group and $a\in G$,
$\overline{\psi(a)}=\psi(-a)$.
\end{lemma}
\begin{proof}
Since $|\psi(a)|=1$, $\overline{\psi(a)}=\psi(a)^{-1}=\psi(-a)$.
\end{proof}

\begin{theorem}[Self-adjointness for symmetric $S$]
If $S=-S$, then $\lambda_\psi(S)\in\R$ for every character $\psi$; equivalently
$A_S$ is self-adjoint.
\end{theorem}
\begin{proof}
$\overline{\lambda_\psi(S)}=\sum_{s\in S}\overline{\psi(s)}=\sum_{s\in S}\psi(-s)
=\sum_{s\in S}\psi(s)=\lambda_\psi(S)$, reindexing $s\mapsto-s$ over $S=-S$.
\end{proof}

\section{Worked example: the cycle}

Let $n\ge3$, $G=\Z/n\Z$, and $S=\{+1,-1\}$; then $\Cay(G,S)$ is the $n$-cycle.

\begin{lemma}
$S=-S$, so $A_S$ is self-adjoint.
\end{lemma}

The characters are $\psi_j(x)=e^{2\pi i jx/n}$; the standard one is $\psi_1$.

\begin{theorem}[Second eigenvalue of the cycle]
For $n\ge3$,
$\displaystyle \lambda_{\psi_1}(S)=e^{2\pi i/n}+e^{-2\pi i/n}=2\cos\!\big(\tfrac{2\pi}{n}\big)$.
\end{theorem}
\begin{proof}
$\lambda_{\psi_1}(S)=\psi_1(1)+\psi_1(-1)=e^{2\pi i/n}+e^{-2\pi i/n}$; apply
$e^{i\theta}+e^{-i\theta}=2\cos\theta$. For $n\ge3$, $1\ne-1$ in $\Z/n\Z$, so $S$
has two elements.
\end{proof}

More generally $\lambda_{\psi_j}(S)=2\cos(2\pi j/n)$; the top eigenvalue is $2$ and
the second-largest is $2\cos(2\pi/n)$.

\begin{theorem}[Positive spectral gap]
For $n\ge3$, $\;2-2\cos\!\big(\tfrac{2\pi}{n}\big)>0$.
\end{theorem}
\begin{proof}
For $n\ge3$, $\theta=2\pi/n\in(0,\pi]$, where $\cos$ is strictly decreasing, so
$\cos\theta<\cos0=1$.
\end{proof}

A Taylor expansion gives $2-2\cos(2\pi/n)=(2\pi/n)^2+O(n^{-4})=\Theta(n^{-2})$,
recovering the classical $\Theta(n^2\log n)$ mixing time of the cycle.

\section{From spectrum to mixing time}

Let $S$ be symmetric, $P=|S|^{-1}A_S$, with eigenvalues
$\mu_\psi=\lambda_\psi(S)/|S|\in[-1,1]$ and $\mu_{\mathrm{triv}}=1$. Assuming the
walk connected and aperiodic, set $\mu_\star=\max_{\psi\ne\mathrm{triv}}|\mu_\psi|$
and $\mathrm{gap}=1-\mu_\star$. Expanding $\delta_0$ in the character basis and
applying the diagonalization mode by mode,
\[
\|P^t\delta_0-\mathrm{unif}\|_2\le\mu_\star^{\,t}\le e^{-\mathrm{gap}\cdot t},
\qquad\text{whence}\qquad
\tau_{\mathrm{mix}}=O\!\Big(\frac{\log|G|}{\mathrm{gap}}\Big).
\]
For the cycle, $\mathrm{gap}=\Theta(n^{-2})$ and $|G|=n$ give
$\tau_{\mathrm{mix}}=\Theta(n^2\log n)$.

\section{A second example: the hypercube}

Let $G=(\Z/2\Z)^d$ and $S=\{e_1,\dots,e_d\}$ (single-bit flips). The characters are
$\chi_T(x)=(-1)^{\sum_{i\in T}x_i}$ for $T\subseteq\{1,\dots,d\}$, giving
\[
\lambda_{\chi_T}(S)=\sum_{i=1}^d(-1)^{[i\in T]}=d-2|T|.
\]
The top eigenvalue is $d$; the second is $d-2$; after normalization the gap is $2/d$,
so $\tau_{\mathrm{mix}}=\Theta(d\log d)$. The whole spectrum $\{d-2k\}$ with
multiplicity $\binom{d}{k}$ falls out of one character computation.

\section{Applications}

The explicit spectral picture feeds directly into applications. In \emph{card
shuffling and statistics}, repeated shuffling is a random walk on a group, and the
abelian case is the exactly solvable model behind harder non-abelian shuffles. In
\emph{Markov chain Monte Carlo}, the number of steps for a reliable sample is the
mixing time, hence the reciprocal spectral gap up to logarithmic factors, which the
character method supplies in closed form for group-structured state spaces. In the
theory of \emph{expander graphs}, a family is expanding exactly when the normalized
gap is bounded below by a constant; the eigenvalue formula $\lambda_\psi(S)=\sum_{s\in
S}\psi(s)$ is the starting point, and the cycle (gap $\Theta(n^{-2})\to0$) is the
canonical non-expander. In \emph{coding theory}, characters of $(\Z/2\Z)^d$ are the
columns of the Walsh--Hadamard transform, so the hypercube spectrum $d-2|T|$ is the
Fourier spectrum of Boolean-function analysis. Finally, in \emph{quantum computation}
the unitarity and periodicity of the shift are the defining features of a
discrete-time quantum walk, whose spectrum on abelian base graphs is again a character
sum.

\section{Discussion and future directions}

For finite abelian groups the spectral analysis of Cayley walks is complete and
explicit. The abelian case is special because irreducible representations are
one-dimensional (characters), so simultaneous diagonalization is literally
diagonalization. Natural extensions:
\begin{enumerate}
\item Establish character orthogonality to obtain a full operator decomposition
$A=\sum_\chi\lambda_\chi P_\chi$.
\item Formalize the mixing-time bound $\tau_{\mathrm{mix}}=O(\mathrm{gap}^{-1}\log|G|)$.
\item Compute exact spectra for products $\prod\Z/n_i\Z$ and the hypercube.
\item Analyze genuinely unitary (coined / Szegedy) quantum walks via the same
character decomposition.
\item Extend to non-abelian groups via irreducible representations, targeting the
random-transposition walk on $S_n$, whose spectral gap is $\Theta(1/n)$.
\end{enumerate}

